  1	/**
  2	 * API Client for Repo Parallelizer GUI.
  3	 *
  4	 * Centralises all HTTP communication with the backend REST API.
  5	 * All methods return Promises. Non-2xx responses throw an Error whose
  6	 * message is taken from the `error` field in the JSON response body.
  7	 *
  8	 * Usage:
  9	 *   import { api } from './api.js';
 10	 *
 11	 *   const repos = await api.repositories.list();
 12	 *   const project = await api.projects.get('my-project');
 13	 */
 14	
 15	// ---------------------------------------------------------------------------
 16	// Internal HTTP helper
 17	// ---------------------------------------------------------------------------
 18	
 19	/**
 20	 * Perform a fetch request and return the parsed JSON body.
 21	 *
 22	 * For 204 No Content responses the Promise resolves with `undefined`.
 23	 * For non-2xx responses, an Error is thrown whose message comes from
 24	 * the `error` field in the JSON response body (falling back to the HTTP
 25	 * status text if the body cannot be parsed).
 26	 *
 27	 * @param {string} method - HTTP method (GET, POST, PUT, DELETE, …).
 28	 * @param {string} url    - Absolute or relative URL.
 29	 * @param {Object} [body] - Optional request body (serialised as JSON).
 30	 * @returns {Promise<*>}
 31	 */
 32	async function request(method, url, body) {
 33	    /** @type {RequestInit} */
 34	    const options = {
 35	        method,
 36	        headers: {
 37	            'Content-Type': 'application/json',
 38	            'Accept': 'application/json',
 39	        },
 40	    };
 41	
 42	    if (body !== undefined) {
 43	        options.body = JSON.stringify(body);
 44	    }
 45	
 46	    const response = await fetch(url, options);
 47	
 48	    // 204 No Content — nothing to parse.
 49	    if (response.status === 204) {
 50	        return undefined;
 51	    }
 52	
 53	    // Attempt to parse JSON for all other responses.
 54	    let json;
 55	    const contentType = response.headers.get('Content-Type') || '';
 56	    if (contentType.includes('application/json')) {
 57	        json = await response.json();
 58	    }
 59	
 60	    if (!response.ok) {
 61	        const message =
 62	            (json && json.error) ? json.error : response.statusText;
 63	        const err = new Error(message);
 64	        err.status = response.status;
 65	        throw err;
 66	    }
 67	
 68	    return json;
 69	}
 70	
 71	// ---------------------------------------------------------------------------
 72	// Shared type definitions
 73	// ---------------------------------------------------------------------------
 74	
 75	/**
 76	 * A project object as returned by the backend REST API.
 77	 *
 78	 * The Go backend serialises struct fields using their Go-style capitalised
 79	 * names (`Id`, `Name`, `Description`, `Repositories`). Future serialiser
 80	 * changes may emit lowercase equivalents (`id`, `name`, `description`,
 81	 * `repositories`). View code **must** normalise both casings:
 82	 *
 83	 * ```js
 84	 * const id   = project.Id   || project.id   || '';
 85	 * const name = project.Name || project.name || id;
 86	 * ```
 87	 *
 88	 * @typedef {Object} ProjectResponse
 89	 * @property {string}   [Id]            - Project ID (Go-capitalised key).
 90	 * @property {string}   [id]            - Project ID (lowercase key).
 91	 * @property {string}   [Name]          - Human-readable project name (Go-capitalised key).
 92	 * @property {string}   [name]          - Human-readable project name (lowercase key).
 93	 * @property {string}   [Description]   - Optional project description (Go-capitalised key).
 94	 * @property {string}   [description]   - Optional project description (lowercase key).
 95	 * @property {Array}    [Repositories]  - Array of associated repository objects (Go-capitalised key).
 96	 * @property {Array}    [repositories]  - Array of associated repository objects (lowercase key).
 97	 */
 98	
 99	/**
100	 * Response shape for the notes display configuration endpoints

  1	/**
  2	 * Repositories View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders a full CRUD management page for all registered repositories:
  5	 *   - Table listing all repositories (ID, Name, URL).
  6	 *   - "Add Repository" inline form (URL required, Name optional, ID optional).
  7	 *   - Inline edit for repository Name per row.
  8	 *   - Delete per row with a confirmation dialog.
  9	 *
 10	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 11	 * @param {Object}      _params   - Route params (none for this route).
 12	 */
 13	
 14	import { api } from '../api.js';
 15	import { showToast } from '../components/toast.js';
 16	import { showConfirm } from '../components/confirm-dialog.js';
 17	import { createFormField, validateRequired } from '../components/form-helpers.js';
 18	import { normaliseRepo } from '../utils/normalise.js';
 19	import { clearElement } from '../utils/dom.js';
 20	import { APP_NAME_SHORT } from '../utils/constants.js';
 21	
 22	// ---------------------------------------------------------------------------
 23	// Table rendering
 24	// ---------------------------------------------------------------------------
 25	
 26	/**
 27	 * Build the `<thead>` element for the repository table.
 28	 *
 29	 * @returns {HTMLElement}
 30	 */
 31	function buildTableHead() {
 32	    const thead = document.createElement('thead');
 33	    const tr    = document.createElement('tr');
 34	
 35	    ['ID', 'Name', 'URL', 'Credential', 'Actions'].forEach((label) => {
 36	        const th = document.createElement('th');
 37	        th.textContent = label;
 38	        tr.appendChild(th);
 39	    });
 40	
 41	    thead.appendChild(tr);
 42	    return thead;
 43	}
 44	
 45	/**
 46	 * Build a single `<tr>` for one repository.
 47	 *
 48	 * The row starts in read mode.  The Name cell renders as a clickable `<a>`
 49	 * link navigating to `#/repositories/:id`.  Clicking Edit switches the Name
 50	 * cell to an inline `<input>` and replaces the action buttons with Save / Cancel.
 51	 * Clicking Delete shows a confirmation dialog and calls the API on confirm.
 52	 *
 53	 * @param {{ id: string, name: string, url: string }} repo
 54	 * @param {function(): void} onDeleted - Callback to refresh the table after deletion.
 55	 * @returns {HTMLTableRowElement}
 56	 */
 57	function buildRepoRow(repo, onDeleted) {
 58	    const tr = document.createElement('tr');
 59	    tr.dataset.repoId = repo.id;
 60	
 61	    // ---- ID cell (read-only) ----
 62	    const idCell = document.createElement('td');
 63	    idCell.className = 'repo-id-cell text-muted';
 64	    idCell.textContent = repo.id;
 65	    tr.appendChild(idCell);
 66	
 67	    // ---- Name cell (editable) ----
 68	    const nameCell = document.createElement('td');
 69	    nameCell.className = 'repo-name-cell';
 70	
 71	    const nameLink = document.createElement('a');
 72	    nameLink.className = 'repo-name-display repo-name-link';
 73	    nameLink.href      = `#/repositories/${encodeURIComponent(repo.id)}`;
 74	    nameLink.textContent = repo.name || '—';
 75	    nameCell.appendChild(nameLink);
