223	/**
224	 * Fetch all workspaces for matching projects and collect status data for the
225	 * given repository. Uses `Promise.allSettled` at each fan-out level so that
226	 * individual fetch failures do not abort the entire load.
227	 *
228	 * @param {string}   repoId       - The repository ID to look for.
229	 * @param {Object[]} allProjects  - Raw project list from `api.projects.list()`.
230	 * @returns {Promise<{ rows: WorkspaceRowDescriptor[], anyFailed: boolean }>}
231	 */
232	async function loadWorkspaceRows(repoId, allProjects) {
233	    let anyFailed = false;
234	
235	    // Step 1: Fetch full project data for all projects in parallel.
236	    const projectResults = await Promise.allSettled(
237	        allProjects.map((p) => {
238	            const pid = p.Id || p.id || '';
239	            return api.projects.get(pid).then((full) => ({ pid, full }));
240	        }),
241	    );
242	
243	    // Step 2: Filter projects that contain this repo.
244	    const matchingProjects = [];
245	    for (const result of projectResults) {
246	        if (result.status === 'rejected') {
247	            anyFailed = true;
248	            continue;
249	        }
250	        const { pid, full } = result.value;

251	        const project = normaliseProject(full);
252	        const contains = project.repositories.some((r) => {
253	            const rid = (typeof r === 'string') ? r : (r.Id || r.id || r.RepositoryId || r.repositoryId || '');
254	            return rid === repoId;
255	        });
256	        if (contains) {
257	            matchingProjects.push({ pid, project });
258	        }
259	    }
260	
261	    // Step 3: Fetch workspaces for each matching project in parallel.
262	    const workspaceResults = await Promise.allSettled(
263	        matchingProjects.map(({ pid }) =>
264	            api.workspaces.list(pid).then((wsList) => ({ pid, wsList })),
265	        ),
266	    );
267	
268	    // Step 4: Fetch status per workspace in parallel.
269	    const statusFetchTasks = [];
270	    for (const result of workspaceResults) {
271	        if (result.status === 'rejected') {
272	            anyFailed = true;
273	            continue;
274	        }
275	        const { pid, wsList } = result.value;
276	        const projectName = matchingProjects.find((mp) => mp.pid === pid)?.project.name || pid;
277	
278	        for (const rawWs of (wsList || [])) {
279	            const ws = normaliseWorkspace(rawWs);
280	            const wid = ws.id;
281	            if (!wid) continue;
282	
283	            statusFetchTasks.push(
284	                api.status.get(pid, wid)
285	                    .then((statusMap) => ({
286	                        pid,
287	                        projectName,
288	                        wid,
289	                        isStable:    wid === STABLE_WS_ID,
290	                        initialized: ws.initialized,
291	                        statusInfo:  (statusMap && statusMap[repoId]) ? statusMap[repoId] : null,
292	                    }))
293	                    .catch(() => {
294	                        // Status fetch failed — include the row but without status data.
295	                        return {
296	                            pid,
297	                            projectName,
298	                            wid,
299	                            isStable:    wid === STABLE_WS_ID,
300	                            initialized: ws.initialized,
301	                            statusInfo:  null,
302	                        };
303	                    }),
304	            );
305	        }
306	    }
307	
308	    const statusResults = await Promise.allSettled(statusFetchTasks);
309	
310	    const rows = [];
311	    for (const result of statusResults) {
312	        if (result.status === 'rejected') {
313	            anyFailed = true;
314	            continue;
315	        }
316	        rows.push(result.value);
317	    }
318	
319	    return { rows, anyFailed };
320	}
