326	/**
327	 * Format a Date as a human-readable relative string.
328	 * e.g. "just now", "3 minutes ago", "2 hours ago", "1 day ago".
329	 *
330	 * @param {Date} date
331	 * @returns {string}
332	 */
333	function formatRelativeTime(date) {
334	    const seconds = Math.floor((Date.now() - date.getTime()) / 1000);
335	    if (seconds < 60) return 'just now';
336	    const minutes = Math.floor(seconds / 60);
337	    if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`;
338	    const hours = Math.floor(minutes / 60);
339	    if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`;
340	    const days = Math.floor(hours / 24);
341	    return `${days} day${days === 1 ? '' : 's'} ago`;
342	}
